mapper.select:
select cmd.command_type as command_type ,count(1) as count from t_ds_error_command cmd JOIN t_ds_workflow_definition tdwd ON tdwd.code = cmd.workflow_definition_code where 1=1
and tdwd.project_code in
#{i}
and cmd.start_time >= #{startTime} and cmd.update_time <= #{endTime}
group by cmd.command_type

select * from t_ds_error_command where workflow_definition_code in
#{id}
order by workflow_instance_priority, id asc
